195	/** Reorder a column within its board; renumber siblings. */
196	export async function moveColumn(columnId: string, toIndex: number): Promise<void> {
197	  await requireAdmin();
198	  const col = await db.boardColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
199	  if (!col) return;
200	  const siblings = await db.boardColumn.findMany({
201	    where: { boardId: col.boardId, NOT: { id: columnId } },
202	    orderBy: { position: "asc" },
203	    select: { id: true },
204	  });
205	  const order = siblings.map((s) => s.id);
206	  const idx = Math.max(0, Math.min(toIndex, order.length));
207	  order.splice(idx, 0, columnId);
208	  await db.$transaction(order.map((id, i) => db.boardColumn.update({ where: { id }, data: { position: i } })));
209	  revalidatePath("/admin/board");
210	}
