214	/** Full-text-ish search over card title, description and comment bodies
215	 *  (Postgres case-insensitive contains). Scoped to a board, or to an app (all
216	 *  its boards). Skips archived cards. */
217	export async function searchCards(
218	  scope: { boardId?: string | null; appId?: string | null },
219	  query: string,
220	): Promise<CardSearchHit[]> {
221	  await requireAdmin();
222	  const q = String(query ?? "").trim();
223	  if (q.length < 2) return [];
224	  const boardWhere =
225	    scope.boardId ? { boardId: scope.boardId } : scope.appId ? { board: { appId: scope.appId } } : {};
226	  const cards = await db.card.findMany({
227	    where: {
228	      archivedAt: null,
229	      ...boardWhere,
230	      OR: [
231	        { title: { contains: q, mode: "insensitive" } },
232	        { description: { contains: q, mode: "insensitive" } },
233	        { comments: { some: { body: { contains: q, mode: "insensitive" } } } },
234	      ],
235	    },
236	    include: {
237	      board: { select: { name: true } },
238	      column: { select: { name: true } },
239	      comments: { where: { body: { contains: q, mode: "insensitive" } }, take: 1, orderBy: { createdAt: "desc" } },
240	    },
241	    orderBy: { updatedAt: "desc" },
242	    take: 50,
243	  });
244	  const lower = q.toLowerCase();
245	  const snippetAround = (text: string): string => {
246	    const i = text.toLowerCase().indexOf(lower);
247	    if (i < 0) return text.slice(0, 120);
248	    const start = Math.max(0, i - 40);
249	    return (start > 0 ? "…" : "") + text.slice(start, i + q.length + 60).trim() + (i + q.length + 60 < text.length ? "…" : "");
250	  };
251	  return cards.map((c) => {
252	    let matchedIn: CardSearchHit["matchedIn"] = "title";
253	    let snippet = c.title;
254	    if (!c.title.toLowerCase().includes(lower)) {
255	      if (c.description.toLowerCase().includes(lower)) {
256	        matchedIn = "description";
257	        snippet = snippetAround(c.description);
258	      } else if (c.comments[0]) {
259	        matchedIn = "comment";
260	        snippet = snippetAround(c.comments[0].body);
261	      }
262	    }
263	    return {
264	      id: c.id,
265	      boardId: c.boardId,
266	      boardName: c.board.name,
267	      columnId: c.columnId,
268	      columnName: c.column.name,
269	      title: c.title,
270	      type: c.type,
271	      priority: c.priority,
272	      snippet,
273	      matchedIn,
274	    };
275	  });
276	}
