297	export async function updateCard(
298	  id: string,
299	  patch: { title?: string; description?: string; type?: string; priority?: string; labels?: string[]; assignee?: string | null },
300	): Promise<{ error?: string }> {
301	  await requireAdmin();
302	  const data: Record<string, unknown> = {};
303	  if (patch.title !== undefined) { const t = patch.title.trim().slice(0, 200); if (!t) return { error: "Title can’t be empty." }; data.title = t; }
304	  if (patch.description !== undefined) data.description = patch.description.slice(0, 20_000);
305	  if (patch.type !== undefined && TYPES.includes(patch.type)) data.type = patch.type;
306	  if (patch.priority !== undefined && PRIORITIES.includes(patch.priority)) data.priority = patch.priority;
307	  if (patch.labels !== undefined) data.labels = patch.labels.map((l) => l.trim().slice(0, 24)).filter(Boolean).slice(0, 8);
308	  if (patch.assignee !== undefined) data.assignee = patch.assignee?.trim().slice(0, 40) || null;
309	  await db.card.update({ where: { id }, data });
310	  revalidatePath("/admin/board");
311	  return {};
312	}
