314	/** Move a card to a column at a position; renumber siblings. */
315	export async function moveCard(cardId: string, toColumnId: string, toIndex: number): Promise<void> {
316	  await requireAdmin();
317	  const card = await db.card.findUnique({ where: { id: cardId }, select: { columnId: true, boardId: true } });
318	  const col = await db.boardColumn.findUnique({ where: { id: toColumnId }, select: { boardId: true } });
319	  if (!card || !col || col.boardId !== card.boardId) return;
320	  const siblings = await db.card.findMany({ where: { columnId: toColumnId, archivedAt: null, NOT: { id: cardId } }, orderBy: { position: "asc" }, select: { id: true } });
321	  const order = siblings.map((s) => s.id);
322	  const idx = Math.max(0, Math.min(toIndex, order.length));
323	  order.splice(idx, 0, cardId);
324	  await db.$transaction([
325	    db.card.update({ where: { id: cardId }, data: { columnId: toColumnId } }),
326	    ...order.map((id, i) => db.card.update({ where: { id }, data: { position: i } })),
327	  ]);
328	  revalidatePath("/admin/board");
329	}
