387	// ---- Execution pipeline ----------------------------------------------------
388	// Moving a card through stages can trigger real work: rendering docs, deploying
389	// to staging, promoting to production, or committing to GitHub. These are NEVER
390	// fired automatically by moveCard — they are only run when a human clicks the
391	// explicit, confirm-gated button in the card modal (see runCardStageAction).
392	// Each run is spawned DETACHED with output captured to a log file; a start
393	// comment is posted immediately and a completion comment (with the log tail) is
394	// posted when the child exits, so the request thread never blocks on a long
395	// deploy.
396	
397	// Fixed command table — actions are chosen from this allowlist only; no user
398	// input is ever interpolated into a shell command. The GitHub commit message is
399	// passed via an environment variable and expanded inside double quotes, so its
400	// contents can't break out into further shell parsing.
401	const STAGE_ACTIONS: Record<StageAction, { label: string; cmd: string; args: string[] }> = {
402	  docs: { label: "Publish to docs", cmd: "node", args: ["scripts/publish-docs.mjs"] },
403	  staging: { label: "Deploy to staging", cmd: "bash", args: ["scripts/deploy-staging.sh"] },
