418	 * Run a pipeline action for a card. Admin-gated. Spawns the mapped script
419	 * detached with output captured to a per-run log, records a start comment, and
420	 * (when the child exits) a completion comment with the log tail. Returns as soon
421	 * as the child is launched — it never waits for a long deploy to finish.
422	 */
423	export async function runCardStageAction(
424	  cardId: string,
425	  action: StageAction,
426	): Promise<{ error?: string; started?: boolean; logPath?: string }> {
427	  const admin = await requireAdmin();
428	  const spec = STAGE_ACTIONS[action];
429	  if (!spec) return { error: "Unknown action." };
430	  const card = await db.card.findUnique({ where: { id: cardId }, select: { id: true, title: true } });
431	  if (!card) return { error: "Card not found." };
432	
433	  await fs.mkdir(STAGE_LOG_DIR, { recursive: true });
434	  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
435	  const logPath = join(STAGE_LOG_DIR, `${cardId}-${action}-${stamp}.log`);
436	
437	  const env: NodeJS.ProcessEnv = { ...process.env };
438	  if (action === "github") {
439	    env.NXEON_COMMIT_MSG = `board: ${card.title} (card ${cardId})`.replace(/\s+/g, " ").slice(0, 180);
440	  }
441	
442	  const author = admin.email.split("@")[0];
443	  await db.cardComment.create({
444	    data: { cardId, authorName: author, body: `▶️ Started **${spec.label}**.\nLog: \`${logPath}\`` },
445	  });
446	
447	  let logFd;
448	  try {
449	    logFd = await fs.open(logPath, "a");
450	  } catch (e) {
451	    return { error: `Could not open log file: ${(e as Error).message}` };
452	  }
453	
454	  try {
455	    const child = spawn(spec.cmd, spec.args, {
456	      cwd: PROJECT_ROOT,
457	      env,
458	      detached: true,
459	      stdio: ["ignore", logFd.fd, logFd.fd],
460	    });
461	    child.unref();
462	    child.on("error", (err) => {
463	      logFd.close().catch(() => undefined);
464	      db.cardComment
465	        .create({ data: { cardId, authorName: "system", body: `❌ **${spec.label}** failed to start: ${err.message}` } })
466	        .catch(() => undefined);
467	    });
468	    child.on("exit", async (code, signal) => {
469	      await logFd.close().catch(() => undefined);
470	      const tail = await readLogTail(logPath);
471	      const status = code === 0 ? "✅ succeeded" : `❌ exited with ${code ?? `signal ${signal}`}`;
472	      await db.cardComment
473	        .create({ data: { cardId, authorName: "system", body: `**${spec.label}** ${status}\n\n\`\`\`\n${tail}\n\`\`\`` } })
474	        .catch(() => undefined);
475	    });
476	  } catch (e) {
477	    await logFd.close().catch(() => undefined);
478	    return { error: `Failed to launch: ${(e as Error).message}` };
479	  }
480	
481	  revalidatePath("/admin/board");
482	  return { started: true, logPath };
483	}
