import { db } from "../lib/db";

// One-shot data script: bind existing board Apps to their real Server rows by IP,
// ensure the studionexis app's display name, and delete the stale `test` app.
// Run: npx tsx scripts/_bind-board-apps.ts   (then delete this file).

const BINDINGS: { slug: string; ip: string }[] = [
  { slug: "soul-pilates", ip: "51.79.226.200" },
  { slug: "studionexis", ip: "51.79.226.215" },
];

async function main() {
  for (const { slug, ip } of BINDINGS) {
    const app = await db.app.findUnique({ where: { slug } });
    if (!app) { console.log(`SKIP  app slug="${slug}" not found`); continue; }
    const server = await db.server.findFirst({ where: { ipAddress: ip }, select: { id: true, name: true } });
    if (!server) { console.log(`SKIP  no server has ipAddress=${ip} — leaving app "${slug}" unbound`); continue; }
    await db.app.update({ where: { id: app.id }, data: { serverId: server.id } });
    console.log(`BOUND app "${slug}" -> server "${server.name}" (${ip})`);
  }

  // Ensure the studionexis app displays as "Studio Nexis" (leave color as-is).
  const nexis = await db.app.findUnique({ where: { slug: "studionexis" } });
  if (nexis && nexis.name !== "Studio Nexis") {
    await db.app.update({ where: { id: nexis.id }, data: { name: "Studio Nexis" } });
    console.log(`RENAME app "studionexis" name "${nexis.name}" -> "Studio Nexis"`);
  } else if (nexis) {
    console.log(`OK    app "studionexis" name already "${nexis.name}"`);
  }

  // Delete the stale `test` app. Should have 0 boards; if not, orphan them first.
  const test = await db.app.findUnique({ where: { slug: "test" }, include: { _count: { select: { boards: true } } } });
  if (!test) {
    console.log(`OK    no app with slug="test" to delete`);
  } else {
    if (test._count.boards > 0) {
      await db.board.updateMany({ where: { appId: test.id }, data: { appId: null } });
      console.log(`REASSIGN ${test._count.boards} board(s) off "test" -> null`);
    }
    await db.app.delete({ where: { id: test.id } });
    console.log(`DELETE app "test" (had ${test._count.boards} board(s))`);
  }
}

main()
  .then(() => db.$disconnect())
  .catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });
